INSERT INTO `steps` (`id`, `title`, `description`, `duration`, `recipe_id`, `step_order`) VALUES
                                                                                              (8, '1ο', 'Ρίχνουμε σε μια μεγάλη λεκάνη το αλεύρι, προσθέτουμε την ξηρή μαγιά και τη ζάχαρη και ανακατεύουμε με ένα κουτάλι.', 10, 1, 0),
                                                                                              (9, '2ο', 'Διαλύουμε το αλάτι στο χλιαρό νερό ανακατεύοντας με κουτάλι.', 10, 1, 1),
                                                                                              (10, '3ο', 'Προσθέτουμε σταδιακά το χλιαρό αλατόνερο στο αλεύρι και δουλεύουμε το μείγμα με τα χέρια μέχρι να σχηματιστεί μια ομοιογενής ζύμη που μαζεύεται σε μπάλα και ξεκολλά από τα τοιχώματα της λεκάνης.', 10, 1, 2),
                                                                                              (11, '4ο', 'Τη μεταφέρουμε στον πάγκο και τη ζυμώνουμε για 10 λεπτά, μέχρι να γίνει λεία, ελαστική και να μην κολλάει στα δάχτυλα. Αν χρειαστεί, πασπαλίζουμε ελαφρώς τα χέρια και τον πάγκο με αλεύρι.', 10, 1, 3),
                                                                                              (12, '5ο', 'Όταν γίνει λεία και εύπλαστη η ζύμη, τη μαζεύουμε σε μπάλα και τη μεταφέρουμε με τις ενώσεις προς τα κάτω σε ελαφρώς λαδωμένο μπολ.', 10, 1, 4),
                                                                                              (13, '6ο', 'Τη σκεπάζουμε καλά και την αφήνουμε σε ζεστό μέρος για 45 λεπτά, να διπλασιαστεί σε όγκο.', 10, 1, 5),
                                                                                              (14, '7ο', 'Μόλις φουσκώσει, τη βγάζουμε στον πάγκο, τη ζυμώνουμε απαλά για να ξεφουσκώσει και την ξαναβάζουμε στο λαδωμένο μπολ. Τη σκεπάζουμε και την αφήνουμε για άλλα 30 λεπτά να φουσκώσει ξανά.', 10, 1, 6),
                                                                                              (15, '8ο', 'Αφού γίνει και το δεύτερο φούσκωμα, βγάζουμε τη ζύμη στον πάγκο και την πιέζουμε να ξεφουσκώσει. Τη χωρίζουμε σε δύο ίσα μέρη και πλάθουμε τα ψωμιά τυλίγοντας τη ζύμη και τσιμπώντας τις άκρες στην ένωση.', 10, 1, 7),
                                                                                              (16, '9ο', 'Τα μεταφέρουμε σε ταψί πασπαλισμένο με αλεύρι ή στρωμένο με αντικολλητικό χαρτί. Τα σκεπάζουμε και τα αφήνουμε για 30 λεπτά να φουσκώσουν και πάλι.', 10, 1, 8),
                                                                                              (17, '10ο', 'Τέλος, χαράζουμε με κοφτερό μαχαίρι την επιφάνεια των ψωμιών σε ένα-δύο σημεία.', 10, 1, 9),
                                                                                              (18, '11ο', 'Ψήνουμε σε καλά προθερμασμένο φούρνο, στους 200°C, στον αέρα, στη μεσαία σχάρα, για 35-40 λεπτά, μέχρι να ροδίσουν καλά', 40, 1, 10),
                                                                                              (33, 'Οδηγίες', 'Η φριτέζα αέρος που χρησιμοποιήθηκε για τη συγκεκριμένη συνταγή έχει ορθογώνιο κάδο, χωρητικότητα 8 λίτρα και ισχύ 1700 Watt.  ', 0, 2, 0),
                                                                                              (34, '1ο', 'Κόβουμε στη μέση τις σκελίδες σκόρδου και τις ρίχνουμε στον πολυκόφτη. ', 1, 2, 1),
                                                                                              (35, '2ο', 'Προσθέτουμε το ελαιόλαδο και χτυπάμε μέχρι να πολτοποιηθεί το σκόρδο. ', 1, 2, 2),
                                                                                              (36, '3ο', 'Ρίχνουμε τη μουστάρδα και χτυπάμε ξανά μέχρι να ενσωματωθεί στο μείγμα. ', 1, 2, 3),
                                                                                              (37, '4ο', 'Κόβουμε το κρεμμύδι σε μεγάλα κομμάτια, ανοίγουμε τα κομμάτια με τα χέρια μας και τα βάζουμε σε ένα μεγάλο μπολ. ', 2, 2, 4),
                                                                                              (38, '5ο', 'Κόβουμε τις πιπεριές σε τετράγωνα κομμάτια και τα βάζουμε και αυτά στο μπολ. ', 1, 2, 5),
                                                                                              (39, '6ο', 'Προσθέτουμε στο μπολ το ξίδι, τη ρίγανη, αλάτι και πιπέρι. ', 1, 2, 6),
                                                                                              (40, '7ο', 'Φοράμε γάντια, κόβουμε τα φιλέτα κοτόπουλου σε τετράγωνα κομμάτια και τα ρίχνουμε στο μπολ. ', 2, 2, 7),
                                                                                              (41, '8ο', 'Ανακατεύουμε με τα χέρια μας μέχρι να μαριναριστούν καλά το κοτόπουλο και τα λαχανικά. ', 2, 2, 8),
                                                                                              (42, '9ο', 'Προσθέτουμε τη μαρινάδα από τον πολυκόφτη και ανακατεύουμε ξανά. ', 1, 2, 9),
                                                                                              (43, '10ο', 'Σε αυτό το στάδιο προαιρετικά καλύπτουμε το μπολ με διάφανη μεμβράνη και μεταφέρουμε στο ψυγείο για 6-12 ώρες. ', 360, 2, 10),
                                                                                              (44, '11ο', 'Περνάμε σε 3 μεταλλικές σούβλες μήκους 30 εκ. εναλλάξ τα κομμάτια κοτόπουλου και λαχανικών. ', 5, 2, 11),
                                                                                              (45, '12ο', 'Μεταφέρουμε τα κοντοσούβλια στον κάδο της φριτέζας αέρος και ψήνουμε στους 200°C για 30 λεπτά. (Στον μισό χρόνο αναποδογυρίζουμε τα κοντοσούβλια.) ', 30, 2, 12),
                                                                                              (46, '13ο', 'Βγάζουμε από τον κάδο και σερβίρουμε με πατάτες τηγανητές. ', 3, 2, 13),
                                                                                              (47, '1o', 'Ρίχνουμε στον πολυκόφτη τα μπισκότα και τα φιστίκια, και χτυπάμε μέχρι να θρυματιστούν.', 1, 3, 0),
                                                                                              (48, '2o', 'Μοιράζουμε το μείγμα σε 4-6 ποτήρια και αφήνουμε στην άκρη.', 2, 3, 1),
                                                                                              (49, '3o', 'Ρίχνουμε στον πολυκόφτη το γιαούρτι, το τυρί cottage, το μέλι, την πραλίνα και το εκχύλισμα βανίλιας, και χτυπάμε καλά μέχρι να ομοιογενοποιηθούν τα υλικά και να έχουμε μια λεία κρέμα.', 5, 3, 2),
                                                                                              (50, '4o', 'Μοιράζουμε την κρέμα στα ποτήρια και προσθέτουμε από πάνω την πραλίνα φιστικιού.', 1, 3, 3),
                                                                                              (51, '5o', 'Ρίχνουμε τα φιστίκια Αιγίνης και σερβίρουμε.', 1, 3, 4);
